INSERT INTO changelog (title, body, created_at) VALUES ('Стартапи: відповіді на відкриті питання', 'У стартапі на «Огляді» в блоці «Відкриті питання» (ризики й невідомі до запуску) тепер можна відповідати. Натисни питання, впиши відповідь (що зʼясували, цифри, від кого) і тисни «✓ Відповісти і закрити». Або «Джері, допоможи відповісти»: він скаже, що вже відомо, як перевірити, і дасть чернетку відповіді. Закриті питання з відповідями лежать у «Відповіли» і йдуть Джері в контекст проєкту.', datetime('now'));
